B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

def check_template(counts, blob, check):
    """Raise when the packed object priors are damaged (palette size, blob bytes, weighted checksum)."""
    n_colours, n_bytes, expected = check
    data = np.concatenate([blob, (counts % 256).astype(np.uint8), (counts // 256).astype(np.uint8)]).astype(np.uint64)
    got = int((data * (np.arange(len(data), dtype=np.uint64) % 251 + 1)).sum() % 4294967291)
    if len(blob) != n_bytes or len(counts) != n_colours or counts.sum() * 3 + n_colours * 3 != n_bytes or got != expected:
        raise ValueError(f"object template priors are damaged: bytes {len(blob)}, colours {len(counts)}, checksum {got}")

def load_template(lo, span, counts, check, blob_text):
    """Decode a packed template to (xyz (N,3) in the object frame, rgb (N,3) uint8)."""
    counts = np.asarray(counts, np.int64); codes = np.frombuffer(B64.encode("ascii"), np.uint8); order = np.argsort(codes)
    v = order[np.searchsorted(codes[order], np.frombuffer(blob_text.encode("ascii"), np.uint8))].reshape(-1, 4).astype(np.uint32)
    word = (v[:, 0] << 18) | (v[:, 1] << 12) | (v[:, 2] << 6) | v[:, 3]
    blob = np.stack([word >> 16, (word >> 8) & 255, word & 255], axis=1).astype(np.uint8).reshape(-1); check_template(counts, blob, check)
    palette = blob[:3 * len(counts)].reshape(-1, 3); q = blob[3 * len(counts):].reshape(-1, 3).astype(float)
    return np.asarray(lo) + q / 255 * np.asarray(span), palette[np.repeat(np.arange(len(counts)), counts)]

