        if len(pts) < 60: continue
        center = np.median(pts, axis=0); normal = np.linalg.svd(pts - center, full_matrices=False)[2][-1]
        if abs(normal[2]) > .3 or np.median(np.abs((pts - center) @ normal)) > .012 or not .5 < center[2] < 1.7: continue
