    def dispatch(self, phase, action, q, cams, base, inverse):
        handlers = {"search": self.phase_search, "navigate": self.phase_navigate, "raise_hand": self.phase_raise_hand, "settle_view": self.phase_settle_view, "pregrasp": self.phase_pregrasp,
                    "descend": self.phase_descend, "close": self.phase_close, "lift": self.phase_lift, "reopen": self.phase_reopen, "carry": self.phase_carry, "inspect_marker": self.phase_inspect_marker, "find_tv": self.phase_find_tv,
                    "place_navigate": self.phase_place_navigate, "place": self.phase_place, "release": self.phase_release, "retract": self.phase_retract, "press_power": self.phase_press_power, "verify_power": self.phase_verify_power,
                    "nudge": self.phase_nudge}
